// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner, address newOwner2) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner2 != address(0));
        vm.assume(newOwner != newOwner2);
        vm.assume(newOwner != address(this));

        // current owner (test contract) transfers ownership to newOwner
        c.setOwner(newOwner);

        // the new owner transfers ownership to a further distinct address
        vm.prank(newOwner);
        c.setOwner(newOwner2);

        // rule: owner is always the address chosen by the current owner's call
        assertTrue(c.owner() == newOwner2);
    }
}
